import json
cur = json.load(open('/data/repo/flake.lock'))
tmp = json.load(open('/tmp/opencode/tmpflake/flake.lock'))
key = lambda o: o['locked']['type']+'/'+o['locked']['owner']+'/'+o['locked']['repo']
c = {key(n): dict(n['locked']) for n in cur['nodes'].values() if 'locked' in n}
t = {key(n): dict(n['locked']) for n in tmp['nodes'].values() if 'locked' in n}
for k in sorted(set(c)|set(t)):
    if c.get(k)!=t.get(k):
        print('DIFF', k); print(' cur:', c.get(k)); print(' tmp:', t.get(k))
print('remaining current lock nodes:', sorted(c))
print('remaining temp lock nodes:', sorted(t))
EOF

